import{_ as e,o as t,c as i,ag as l}from"./chunks/framework.DUTPmUpA.js";const _=JSON.parse('{"title":"Важность значенийabilityValues","description":"","frontmatter":{"title":"Важность значенийabilityValues","author":"Noya","steamId":"76561198046984233","date":"12.12.2014"},"headers":[],"relativePath":"abilities/the-importance-of-abilityvalues-values.md","filePath":"abilities/the-importance-of-abilityvalues-values.md"}'),o={name:"abilities/the-importance-of-abilityvalues-values.md"};function s(r,a,u,n,p,c){return t(),i("div",null,[...a[0]||(a[0]=[l('<h2 id="_014" tabindex="-1">014 <a class="header-anchor" href="#_014" aria-label="Permalink to &quot;014&quot;">​</a></h2><h1 id="важность-значенииabilityvalues" tabindex="-1">Важность значенийabilityValues <a class="header-anchor" href="#важность-значенииabilityvalues" aria-label="Permalink to &quot;Важность значенийabilityValues&quot;">​</a></h1><p><em>Чтобы указать числовые значения, вы можете ввести число или использовать форматирование <code>%name</code> для получения значений из блока «AbilityValues» способности. Преимущество использования синтаксиса <code>%name</code> заключается в том, что значение может меняться по мере повышения уровня способности, а числовое значение можно форматировать во всплывающие подсказки.</em></p><p>При кодировании способностей или предметов <strong>не</strong> попадайте в ловушку, заменяя использование переменныхabilityValues константой (т. е. записывая <code>&quot;Duration&quot; &quot;12&quot;</code>, <code>&quot;MODIFIER_PROPERTY_MOVESPEED_BONUS_PERCENTAGE&quot; &quot;-30&quot;</code> или выполняя аналогичные назначения в сценариях lua), думая, что она будет использоваться только один раз.</p><p>При этом есть <strong>2 проблемы</strong></p><ul><li><p>Подсказки сложны.</p><p>Если вы не используете «AbilityValues» для каждой переменной, то, когда вы приступите к созданию всплывающих подсказок, вы обнаружите, что создать качественные строки в стиле Dota практически невозможно, потому что ваше описание заклинания должно иметь прямые копии значений, которые вы вложили в способность. Что еще хуже, если вы когда-нибудь внесете изменение в статическое число в своей способности, управляемой данными, вам также потребуется обновить файл addon_english.txt.</p></li><li><p>Согласованность между Lua и ключевыми значениями</p><p>Изменение значения ключа повлияет не только на данные, но и на сценарии, и легко внести изменения и забыть распространить это изменение на файл .lua. Правильные ссылки на специальные предложения также устраняют эту проблему.</p></li></ul><br><p><strong>TL;DR</strong>: используйте как можно больше значенийabilityValues, тогда изменение/балансировку ваших способностей можно будет выполнить, просто изменив эти переменные, и это будет распространяться на остальную часть игрового режима.</p>',8)])])}const b=e(o,[["render",s]]);export{_ as __pageData,b as default};
